const VOTE_EXPIRATION_MS = VOTE_EXPIRATION_DAYS * 24 * 60 * 60 * 1000;
const VXT_EXCHANGE_RATE = 0.01; // 1 VXT = 0.01 $
const MIN_BALANCE_RESERVE = 20; // Solde minimum à conserver

