      const confirmProfile = window.confirm("Vous n'avez pas configuré de méthode de paiement. Voulez-vous aller sur votre profil pour le faire ?");
      if (confirmProfile) {
        navigate('/profile');
      }
      return;
    }
    setShowWithdrawModal(true);
    setWithdrawStep('input');
    setWithdrawAmount('');
    setWithdrawConfirmAmount('');
  };

  const handleProceedToConfirmation = () => {
    if (!user) return;
    const amount = parseInt(withdrawAmount);
    if (isNaN(amount) || amount <= 0 || amount > user.walletBalance) return;
    setWithdrawStep('confirm');
    setWithdrawConfirmAmount('');
  };

  const handleExecuteWithdraw = () => {
    if (!user) return;
    const amount = parseInt(withdrawAmount);

    // Security check: values must match
    if (withdrawAmount !== withdrawConfirmAmount) return;

    if (isNaN(amount) || amount <= 0 || amount > user.walletBalance) return;

    setWithdrawStep('processing');

    // Simulate API call
    setTimeout(() => {
      const transaction: Transaction = {
        id: `tx_${Date.now()}`,
        type: 'WITHDRAWAL',
        amount: -amount,
        description: `Retrait vers ${user.paymentConfig?.method === PaymentMethod.PAYPAL ? 'PayPal' : 'Banque'}`,
        timestamp: Date.now()
      };

      const updatedUser = { 
        ...user, 
        walletBalance: user.walletBalance - amount,
        transactions: [transaction, ...(user.transactions || [])]
      };
