    const country = user.country || 'International';
    acc[country] = (acc[country] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const countries = Object.keys(countryStats).sort();

  // Calculate counts per expertise level
  const levelStats = users.reduce((acc, user) => {
    const level = user.expertLevel;
    acc[level] = (acc[level] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Calculate counts per social activity
  const socialStats = users.reduce((acc, user) => {
    const activity = user.socialActivity || 'Non spécifié';
    acc[activity] = (acc[activity] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

