           setNotificationMsg("Analyse chargée depuis le cache");
           setTimeout(() => setNotificationMsg(null), 3000);
           return;
        }
      } catch (e) {
        console.warn("Invalid cache data", e);
        sessionStorage.removeItem(cacheKey);
